<template>
  <AppMultiComboboxQuery
    v-if="isMultiple"
    :value="value"
    :items="selectItems"
    :property-name="propertyName"
    :null-is-all="nullIsAll"
    :loading="isLoading"
    :error="error"
    :placeholder="placeholder"
    :input-placeholder="inputPlaceholder"
    :items-plural-name="itemsPluralName"
    :empty-text="emptyText"
    :icon="icon || FilterIcon"
    :label="label"
    :is-first-page-only="isFirstPageOnly"
    @change="onChange"
  />
  <AppComboboxQuery
    v-else
    :value="value ? value[0] : null"
    :items="selectItems"
    :property-name="propertyName"
    :null-is-all="nullIsAll"
    :loading="isLoading"
    :error="error"
    :placeholder="placeholder"
    :input-placeholder="inputPlaceholder"
    :items-plural-name="itemsPluralName"
    :empty-text="emptyText"
    :icon="icon || FilterIcon"
    :label="label"
    :is-first-page-only="isFirstPageOnly"
    @change="onChange"
  />
</template>
<script setup lang="ts">
import { getSelectorProjectList, type GetSelectorProjectListResponse, type ProjectStatus } from '~/client';
import { FilterIcon } from 'lucide-vue-next';

const props = withDefaults(
  defineProps<{
    value: string[] | null;
    propertyName: string;
    statuses: ProjectStatus[];
    assignedUserIds?: string[];

    placeholder: string;
    inputPlaceholder: string;
    emptyText: string;
    nullIsAll: boolean;
    itemsPluralName: string;
    icon?: any;
    label?: string;
    isMultiple?: boolean;
    isFirstPageOnly?: boolean;
  }>(),
  {
    assignedUserIds: undefined,
    icon: undefined,
    label: undefined,
    isMultiple: true,
    isFirstPageOnly: true,
  }
);

const emit = defineEmits(['change']);

const { data, isLoading, error } = useQuery({
  key: () =>
    ['selector-projects-list', ...props.statuses, ...(props.assignedUserIds ?? []), String(props.isMultiple)] as const,
  query: (): Promise<GetSelectorProjectListResponse> =>
    getSelectorProjectList({
      composable: '$fetch',
      query: { statuses: props.statuses, assigned_user_ids: props.assignedUserIds },
    }),
});

const selectItems = computed(() => {
  return (
    data.value?.items.map((project) => ({
      name: project.name,
      value: project.id,
    })) || []
  );
});

function onChange(value: any) {
  emit('change', value);
}
</script>
